questionvariables.text:
/* 1. Generate a sensible ladder length and angle */
ladder_length : rand_with_step(3.0, 10.0, 0.5); 
angle_with_ground : rand_with_step(35, 75, 1);  

/* 2. Convert to radians for Maxima's trig functions */
rad_angle : angle_with_ground * %pi / 180;

/* 3. Compute the exact float answers */
exact_height : float(ladder_length * sin(rad_angle));
exact_base : float(ladder_length * cos(rad_angle));

/* 4. Prepare rounded versions for the worked solution display (2 d.p.) */
height_on_wall : float(round(exact_height * 100) / 100);
distance_from_wall : float(round(exact_base * 100) / 100);
